    expected_category: "Other"
  },
  {
    id: 15,
    customer_message: "I was charjed twise for my subscription. Can you fix the payment?",
    expected_category: "Billing"
  }
);


return testCases.map(testCase => ({
  json: testCase
}));

const predictions = $input.all();
const totalCases = $("10 Cases").all().length;


if (predictions.length === 0 || predictions.length > totalCases) {
  throw new Error(
    `Invalid prediction count: ${predictions.length} for ${totalCases} test cases`
  );
}


const validCategories = [
  "Billing", "Sales", "Support", "Other"
];

const results = predictions.map((item, index) => {
  const testCase = $("10 Cases").itemMatching(index).json;

  const raw =
    item.json.output?.[0]?.content?.[0]?.text;

  let predicted = raw?.category;

  if (typeof raw === "string") {
    try {
      predicted = JSON.parse(raw).category;
    } catch {
      predicted = null;
    }
  }

  const correct =
    validCategories.includes(predicted) &&
    predicted === testCase.expected_category;

  return {
    id: testCase.id,
    customer_message: testCase.customer_message,
    expected_category: testCase.expected_category,
    predicted_category: predicted ?? "Invalid",
    correct
  };
});

const total = results.length;
const correct = results.filter(r => r.correct).length;
const incorrect = total - correct;

const accuracy = total > 0
  ? Number(((correct / total) * 100).toFixed(2))
  : 0;

return [{
  json: {
    total,
    correct,
    incorrect,
    accuracy_percent: accuracy,
    results
  }
}];

const evaluation = $input.first().json;
const results = evaluation.results;

if (!Array.isArray(results)) {
  throw new Error("Evaluation results not found");
}

const categories = [
  "Billing",
  "Sales",
  "Support",
  "Other"
];

const categoryMetrics = categories.map(category => {
  const expected = results.filter(
    r => r.expected_category === category
  );

  const predicted = results.filter(
    r => r.predicted_category === category
  );

  const correct = expected.filter(
    r => r.predicted_category === category
  ).length;

  const precision = predicted.length > 0
    ? correct / predicted.length
    : 0;

  const recall = expected.length > 0
    ? correct / expected.length
    : 0;

  const f1 = precision + recall > 0
    ? (2 * precision * recall) / (precision + recall)
    : 0;

  return {
    category,
    expected_count: expected.length,
    predicted_count: predicted.length,
    correct,
    precision_percent: Number(
      (precision * 100).toFixed(2)
    ),
    recall_percent: Number(
      (recall * 100).toFixed(2)
    ),
    f1_percent: Number(
      (f1 * 100).toFixed(2)
    )
  };
});

return [{
  json: {
    total: evaluation.total,
    overall_accuracy_percent:
      evaluation.accuracy_percent,
    category_metrics: categoryMetrics
  }
}];

const evaluation = $("Evaluate Predictions").first().json;
const results = evaluation.results;

if (!Array.isArray(results)) {
  throw new Error("Evaluation results not found");
}

const categories = [
  "Billing",
  "Sales",
  "Support",
  "Other"
];

const matrix = {};

for (const actual of categories) {
  matrix[actual] = {};

  for (const predicted of categories) {
    matrix[actual][predicted] = 0;
  }
}

for (const result of results) {
  const actual = result.expected_category;
  const predicted = result.predicted_category;

  if (
    !categories.includes(actual) ||
    !categories.includes(predicted)
  ) {
    throw new Error(
      `Invalid category in test ${result.id}`
    );
  }

  matrix[actual][predicted]++;
}

return [{
  json: {
    total: results.length,
    accuracy_percent: evaluation.accuracy_percent,
    confusion_matrix: matrix
  }
}];

const evaluation = $("Evaluate Predictions").first().json;
const metrics = $("Category Metrics").first().json;
const matrixData = $input.first().json;

const model = "GPT-6-LUNA";
const evaluatedAt = new Date().toISOString();

const categories = [
  "Billing",
  "Sales",
  "Support",
  "Other"
];

if (
  !Array.isArray(evaluation.results) ||
  !Array.isArray(metrics.category_metrics) ||
  !matrixData.confusion_matrix
) {
  throw new Error("Missing evaluation data");
}

const failedCases = evaluation.results.filter(
  result => !result.correct
);

const report = [];

report.push("# AI Classification Evaluation Report");
report.push("");
report.push(`Evaluation date (UTC): ${evaluatedAt}`);
report.push(`Model: ${model}`);
report.push("Workflow: AI Lab 03 - Partial Failure Simulation");
report.push("");

report.push("## Overall Results");
report.push("");
report.push(`Total test cases: ${evaluation.total}`);
report.push(`Correct predictions: ${evaluation.correct}`);
report.push(`Incorrect predictions: ${evaluation.incorrect}`);
report.push(`Accuracy: ${evaluation.accuracy_percent}%`);
report.push("");

report.push("## Category Performance");
report.push("");
report.push("| Category | Cases | Precision | Recall | F1 |");
report.push("|---|---:|---:|---:|---:|");

for (const m of metrics.category_metrics) {
  report.push(
    `| ${m.category} | ${m.expected_count} | ` +
    `${m.precision_percent}% | ` +
    `${m.recall_percent}% | ${m.f1_percent}% |`
  );
}

report.push("");
report.push("## Confusion Matrix");
report.push("");
report.push("Rows = actual category; columns = predicted category.");
report.push("");
report.push("| Actual | Billing | Sales | Support | Other |");
report.push("|---|---:|---:|---:|---:|");

for (const actual of categories) {
  const row = matrixData.confusion_matrix[actual];

  report.push(
    `| ${actual} | ` +
    categories.map(c => row[c]).join(" | ") +
    " |"
  );
}

report.push("");
report.push("## Failed Test Cases");
report.push("");

if (failedCases.length === 0) {
  report.push("No classification errors detected.");
} else {
  for (const test of failedCases) {
    report.push(`### Test ${test.id}`);
    report.push(`Message: ${test.customer_message}`);
    report.push(`Expected: ${test.expected_category}`);
    report.push(`Predicted: ${test.predicted_category}`);
    report.push("");
  }
}

report.push("");
report.push("## Evaluation Limitations");
report.push("");
report.push("- Small, manually designed test dataset.");
report.push("- Results do not guarantee production accuracy.");
report.push("- Real-world customer messages require further testing.");
report.push("- API reliability and latency are not evaluated.");
report.push("- Future prompt or model changes require regression tests.");

return [{
  json: {
    report_generated_at: evaluatedAt,
    model,
    total: evaluation.total,
    accuracy_percent: evaluation.accuracy_percent,
    failed_cases: failedCases,
    report_markdown: report.join("\n")
  }
}];

const failedItems = $input.all();

return failedItems.map((item, index) => {
  let testCase = null;

  // Retrieve the original test case through item linking.
  try {
    testCase = $("10 Cases").itemMatching(index).json;
  } catch (error) {
    // Keep the error record even if linking is unavailable.
  }

  const rawError = item.json.error ?? item.json;

  const errorMessage =
    typeof rawError === "string"
      ? rawError
      : rawError.message ??
        item.json.message ??
        "Unknown OpenAI API error";

  return {
    json: {
      event_type: "api_failure",
      test_id: testCase?.id ?? null,
      customer_message:
        testCase?.customer_message ?? null,
      expected_category:
        testCase?.expected_category ?? null,
      error_message: String(errorMessage),
      captured_at: new Date().toISOString()
    },
    pairedItem: { item: index }
  };
});

const failures = $input.all().map(item => item.json);

const categories = [
  "Billing",
  "Sales",
  "Support",
  "Other"
];

const failuresByCategory = {};

for (const category of categories) {
  failuresByCategory[category] = 0;
}

let unknownCategoryCount = 0;

for (const failure of failures) {
  if (failure.event_type !== "api_failure") {
    throw new Error("Unexpected input record");
  }

  const category = failure.expected_category;

  if (categories.includes(category)) {
    failuresByCategory[category]++;
  } else {
    unknownCategoryCount++;
  }
}

const affectedTestIds = [
  ...new Set(
    failures
      .map(f => f.test_id)
      .filter(id => id !== null && id !== undefined)
  )
];

return [{
  json: {
    event_type: "api_failure_summary",
    total_api_failures: failures.length,
    failures_by_category: failuresByCategory,
    unknown_category_count: unknownCategoryCount,
    affected_test_ids: affectedTestIds,
    failure_details: failures.map(f => ({
      test_id: f.test_id,
      expected_category: f.expected_category,
      error_message: f.error_message,
      captured_at: f.captured_at
    })),
    summary_generated_at: new Date().toISOString()
  }
}];

const testCases = $("10 Cases").all().map(item => item.json);
const evaluation = $("Evaluate Predictions").first().json;
const report = $input.first().json;

if (!Array.isArray(evaluation.results)) {
  throw new Error("Missing evaluation results");
}

const totalExpected = testCases.length;

if (totalExpected === 0) {
  throw new Error("No test cases found");
}

const expectedIds = testCases.map(test => String(test.id));

if (new Set(expectedIds).size !== totalExpected) {
  throw new Error("Duplicate test case IDs");
}

const predictionIds = evaluation.results.map(result => {
  if (result.id === null || result.id === undefined) {
    throw new Error("Prediction missing test ID");
  }
  return String(result.id);
});

const predictedIds = new Set(predictionIds);

if (predictedIds.size !== predictionIds.length) {
  throw new Error("Duplicate prediction IDs");
}

for (const id of predictedIds) {
  if (!expectedIds.includes(id)) {
    throw new Error(`Unexpected prediction ID: ${id}`);
  }
}

const completed = predictedIds.size;

const missingTestIds = testCases
  .filter(test => !predictedIds.has(String(test.id)))
  .map(test => test.id);

const coveragePercent = Number(
  ((completed / totalExpected) * 100).toFixed(2)
);

const coverageStatus =
  completed === totalExpected ? "complete" : "partial";

const coverageSection = [
  "",
  "## Evaluation Coverage",
  "",
  `Expected test cases: ${totalExpected}`,
  `Completed predictions: ${completed}`,
  `Missing predictions: ${missingTestIds.length}`,
  `Evaluation coverage: ${coveragePercent}%`,
  `Coverage status: ${coverageStatus}`,
  "",
  "Missing test IDs: " +
    (missingTestIds.length
      ? missingTestIds.join(", ")
      : "None"),
  "",
  "Missing predictions require investigation.",
  "They are not automatically classified as API failures."
].join("\n");

return [{
  json: {
    ...report,
    expected_test_cases: totalExpected,
    completed_predictions: completed,
    missing_predictions: missingTestIds.length,
    missing_test_ids: missingTestIds,
    evaluation_coverage_percent: coveragePercent,
    coverage_status: coverageStatus,
    report_markdown:
      report.report_markdown + "\n" + coverageSection
  }
}];

const testCases = $input.all();

if (testCases.length !== 15) {
  throw new Error(
    `Expected 15 test cases, received ${testCases.length}`
  );
}

// Simulate successful predictions for the first 12 cases.
// Cases 13, 14, and 15 will have no predictions.

const successfulCases = testCases.slice(0, 12);

return successfulCases.map((item, index) => ({
  json: {
    output: [
      {
        type: "message",
        status: "completed",
        content: [
          {
            type: "output_text",
            text: {
              category: item.json.expected_category
            }
          }
        ]
      }
    ]
  },
  pairedItem: {
    item: index
  }
}));

const testCases = $input.all();

if (testCases.length !== 15) {
  throw new Error(
    `Expected 15 cases, received ${testCases.length}`
  );
}

// Simulate API failures for cases 13, 14, and 15.
return testCases.slice(12).map((item, index) => ({
  json: {
    ...item.json,
    error: {
      message: "Simulated OpenAI API failure"
    }
  },
  pairedItem: {
    item: index + 12
  }
}));

const data = $input.first().json;

const missingIds = data.missing_test_ids ?? [];
const failureIds = data.affected_test_ids ?? [];
const failureDetails = data.failure_details ?? [];
const byCategory = data.failures_by_category ?? {};

if (!data.report_markdown) {
  throw new Error("Evaluation report is missing");
}

if (
  data.completed_predictions + data.missing_predictions !==
  data.expected_test_cases
) {
  throw new Error("Evaluation counts do not match");
}

if (missingIds.length !== data.missing_predictions) {
  throw new Error("Missing prediction IDs do not match count");
}

if (
  failureIds.length !== data.total_api_failures ||
  failureDetails.length !== data.total_api_failures
) {
  throw new Error("API failure counts do not match");
}

// Reconcile missing predictions with simulated API failures.
const missingSet = new Set(missingIds.map(String));
const failureSet = new Set(failureIds.map(String));

if (failureSet.size !== failureIds.length) {
  throw new Error("Duplicate API failure IDs");
}

const unmatchedFailures = failureIds.filter(
  id => !missingSet.has(String(id))
);

if (unmatchedFailures.length > 0) {
  throw new Error(
    `API failures without missing predictions: ${unmatchedFailures}`
  );
}

const unexplainedMissing = missingIds.filter(
  id => !failureSet.has(String(id))
);

const lines = [
  "## Simulated API Failure Analysis",
  "",
  `Simulated API failures: ${data.total_api_failures}`,
  `Missing predictions: ${data.missing_predictions}`,
  `Failures matching missing predictions: ${failureIds.length}`,
  `Unexplained missing predictions: ${unexplainedMissing.length}`,
  "",
  "### Failures by Category",
  "",
  "| Category | Failures |",
  "|---|---:|",
  ...["Billing", "Sales", "Support", "Other"].map(
    category => `| ${category} | ${byCategory[category] ?? 0} |`
  ),
  "",
  `Unknown categories: ${data.unknown_category_count ?? 0}`,
  "",
  "### Affected Test Cases",
  "",
  ...failureDetails.map(
    f => `- Test ${f.test_id}: ${f.expected_category} — ${f.error_message}`
  ),
  "",
  "### Unexplained Missing Predictions",
  "",
  unexplainedMissing.length
    ? unexplainedMissing.join(", ")
    : "None",
  "",
  "### Evaluation Interpretation",
  "",
  `Classification accuracy: ${data.accuracy_percent}%`,
  `Evaluation coverage: ${data.evaluation_coverage_percent}%`,
  "",
  "This is a controlled simulation, not a production reliability measurement.",
  "Predictions were generated from expected labels.",
  "API failures were simulated rather than produced by OpenAI."
];

const originalReport = data.report_markdown.replace(
  /^Model:\s*.*$/m,
  "Model: Not invoked (simulated predictions)"
);

const reportMarkdown = [
  "> **SIMULATION ONLY — No real OpenAI API calls were made in this evaluation.**",
  "",
  originalReport,
  "",
  lines.join("\n")
].join("\n");

return [{
  json: {
    ...data,
    evaluation_mode: "simulation",
    reconciled_api_failures: failureIds.length,
    unexplained_missing_predictions: unexplainedMissing.length,
    unexplained_missing_test_ids: unexplainedMissing,
    report_markdown: reportMarkdown
  }
}];
